import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
const token = process.env.INSTAGRAM_ACCESS_TOKEN ?? '';
const userId = process.env.INSTAGRAM_USER_ID ?? '';
assert.ok(process.env.INSTAGRAM_APP_ID && process.env.INSTAGRAM_APP_SECRET, 'the App Dashboard gives the app its Instagram App ID and secret');
const graph = async (path, params = {}) => {
  const url = new URL(`https://graph.instagram.com/v26.0${path}`);
  for (const [k, v] of Object.entries({ ...params, access_token: token })) url.searchParams.set(k, v);
  const answer = await fetch(url);
  const body = await answer.json();
  if (!answer.ok) throw new Error(`GET ${path}: ${answer.status} ${JSON.stringify(body)}`);
  return body;
};
const receiptFile = 'instagram-account.json';
const me = await graph('/me', { fields: 'id,user_id,username,account_type,media_count,followers_count' });
assert.equal(me.user_id, userId, '/me answered ' + JSON.stringify(me));
assert.ok(/^\d+$/.test(me.id) && me.username, '/me answered ' + JSON.stringify(me));
assert.ok(['Business', 'Media_Creator'].includes(me.account_type), 'a professional account: ' + me.account_type);
assert.equal(typeof me.media_count, 'number');
assert.equal(typeof me.followers_count, 'number');
const media = await graph(`/${me.user_id}/media`, { fields: 'id,media_type,timestamp' });
assert.ok(Array.isArray(media.data), 'the media list answered ' + JSON.stringify(media));
const limit = await graph(`/${me.user_id}/content_publishing_limit`, { fields: 'quota_usage,config' });
assert.equal(limit.data[0].config.quota_total, 50);
assert.equal(limit.data[0].config.quota_duration, 86400);
assert.equal(typeof limit.data[0].quota_usage, 'number');
const account = { id: me.id, user_id: me.user_id, username: me.username, account_type: me.account_type, media_count: me.media_count, followers_count: me.followers_count };
if (process.argv[2] === 'readback') {
  const saved = JSON.parse(readFileSync(receiptFile, 'utf8'));
  assert.deepEqual(account, saved.account);
  assert.deepEqual(media.data.map((m) => m.id), saved.media);
  console.log(JSON.stringify({ retained: true, ...saved }));
} else {
  assert.equal(me.media_count, media.data.length);
  const saved = { account, media: media.data.map((m) => m.id), quota_usage: limit.data[0].quota_usage };
  writeFileSync(receiptFile, JSON.stringify(saved) + '\n');
  console.log(JSON.stringify({ read: true, ...saved }));
}
